#!/usr/bin/env node
/**
 * FISH118 D3: produce an isolated, exact-byte, Worker-bundled owner pilot.
 * Safe LOCAL build only: no Cloudflare/GitHub API, D1, secret or deploy.
 *
 * Wrangler's .txt Text-module import gives the Worker a private bundle
 * without a public static-asset binding. It is only served by its own
 * fresh-owner-session, default-OFF D3 route. Generated bytes are ignored
 * by Git; build at the exact reviewed PR head before an approved dry-run.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';
import * as esbuild from 'esbuild';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
const src=path.join(root,'experiments/p3/preview/src');
const entry=path.join(src,'d3-owner-pilot-main.mjs');
const output=path.join(src,'generated/d3-pilot.bundle.txt');
const meta=path.join(src,'generated/d3-pilot.bundle.sha256.json');
const sha256=bytes=>createHash('sha256').update(bytes).digest('hex');
const safeUtf8=bytes=>{
 const text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);
 if(new TextEncoder().encode(text).length!==bytes.length)
  throw Error('Bundled pilot must be canonical UTF-8 text');
 return text;
};

async function main(){
 const result=await esbuild.build({
  entryPoints:[entry],outfile:path.join(src,'generated/d3-pilot.bundle.js'),
  bundle:true,write:false,format:'iife',platform:'browser',target:'es2022',
  minify:true,legalComments:'none',sourcemap:false,
  define:{'process.env.NODE_ENV':'"production"'},
  logLevel:'silent',
 });
 if(result.errors.length||result.outputFiles.length!==1)
  throw Error('Pilot browser build is not a single self-contained bundle');
 const bytes=result.outputFiles[0].contents;
 if(bytes.length<1024||bytes.length>3*1024*1024)
  throw Error('Pilot bundle length outside strict owner-host limits');
 const text=safeUtf8(bytes);
 if(/sourceMappingURL\s*=/.test(text))
  throw Error('A browser sourcemap must not be deployed with pilot code');
 const digest=sha256(bytes);
 await fs.mkdir(path.dirname(output),{recursive:true});
 await fs.writeFile(output,bytes,{flag:'w'});
 const observed=await fs.readFile(output);
 if(sha256(observed)!==digest)throw Error('Written module digest drift');
 const metadata={format:'fishing-d3-pilot-local-build-v1',
  sha256:digest,bytes:observed.length,entry:'d3-owner-pilot-main.mjs',
  output:'generated/d3-pilot.bundle.txt',noDeployment:true};
 await fs.writeFile(meta,JSON.stringify(metadata,null,2)+'\n');
 if(process.argv.includes('--check')){
  const r=await fs.readFile(meta,'utf8');
  if(JSON.parse(r).sha256!==sha256(observed))
   throw Error('Generated manifest failed readback');
 }
 process.stdout.write(JSON.stringify(metadata)+'\n');
}
main().catch(error=>{
 console.error('D3_PILOT_BUILD_FAILED',error.message);
 process.exitCode=1;
});
